        add(id,name,ps,fam,'Đồ họa dữ liệu/ý niệm dựng chính xác bằng SVG hoặc compositor; không nhờ model raster vẽ chữ và số.',spec,id.lower()+'.svg|'+id.lower()+'_preview.png',motion,'Không sinh chữ, số, đường bờ bằng AI. Không đổi tỷ lệ đo để vừa bố cục. Không tạo bằng chứng hoặc quan hệ nhân quả mới.','NGUON_VA_KIEM_CHUNG.md','P1','Kho có đạo cụ198lịch,025thước,126thẻ và một sốSVG; chưa có dữ liệu/cấu trúc đặc thù tập2.')
